const $=(s)=>document.querySelector(s);const lang=document.documentElement.lang;const game=document.body.dataset.game;const page=document.body.dataset.page;const labels={fr:{loading:'Chargement des données publiques…',offline:'Données en direct indisponibles actuellement.',none:'Aucune donnée publiée pour le moment.',driver:'Pilote',team:'Équipe',points:'Points',races:'Courses',wins:'Victoires',podiums:'Podiums',circuit:'Circuit',car:'Voiture',lap:'Meilleur tour',date:'Date',details:'Voir le profil',register:'Inscription',time:'Horaire',filters:'Catégorie',archive:'Résultats historiques du dépôt ACC',legacy:'Ouvrir le site ACC actuel'},en:{loading:'Loading public data…',offline:'Live data is currently unavailable.',none:'No published data yet.',driver:'Driver',team:'Team',points:'Points',races:'Races',wins:'Wins',podiums:'Podiums',circuit:'Circuit',car:'Car',lap:'Best lap',date:'Date',details:'View profile',register:'Register',time:'Schedule',filters:'Category',archive:'Historical results from the ACC repository',legacy:'Open the current ACC site'},de:{loading:'Öffentliche Daten werden geladen…',offline:'Live-Daten sind derzeit nicht verfügbar.',none:'Noch keine veröffentlichten Daten.',driver:'Fahrer',team:'Team',points:'Punkte',races:'Rennen',wins:'Siege',podiums:'Podestplätze',circuit:'Strecke',car:'Fahrzeug',lap:'Beste Runde',date:'Datum',details:'Profil ansehen',register:'Anmelden',time:'Zeitplan',filters:'Kategorie',archive:'Historische Ergebnisse aus dem ACC-Repository',legacy:'Aktuelle ACC-Seite öffnen'},it:{loading:'Caricamento dei dati pubblici…',offline:'Dati in tempo reale non disponibili.',none:'Nessun dato pubblicato.',driver:'Pilota',team:'Squadra',points:'Punti',races:'Gare',wins:'Vittorie',podiums:'Podi',circuit:'Circuito',car:'Auto',lap:'Miglior giro',date:'Data',details:'Vedi profilo',register:'Iscrizione',time:'Orario',filters:'Categoria',archive:'Risultati storici dal repository ACC',legacy:'Apri il sito ACC attuale'},es:{loading:'Cargando datos públicos…',offline:'Los datos en directo no están disponibles.',none:'Todavía no hay datos publicados.',driver:'Piloto',team:'Equipo',points:'Puntos',races:'Carreras',wins:'Victorias',podiums:'Podios',circuit:'Circuito',car:'Coche',lap:'Mejor vuelta',date:'Fecha',details:'Ver perfil',register:'Inscripción',time:'Horario',filters:'Categoría',archive:'Resultados históricos del repositorio ACC',legacy:'Abrir el sitio ACC actual'}}[lang]||{};const base='/'+lang+'/'+game+'/';const api='https://twjpjzalyvbsdpbzhqln.supabase.co/functions/v1';function node(tag,cls,content){const el=document.createElement(tag);if(cls)el.className=cls;if(content!=null)el.textContent=String(content);return el}function link(text,href){const a=node('a','pill',text);a.href=href;return a}function safeExternal(url){try{const u=new URL(url);return u.protocol==='https:'?u.href:null}catch{return null}}function date(s){return s?new Intl.DateTimeFormat(lang,{dateStyle:'medium',timeStyle:'short',timeZone:'Europe/Brussels'}).format(new Date(s)):'—'}function lap(ms){const n=Number(ms);return n>0?`${Math.floor(n/60000)}:${String(Math.floor(n/1000)%60).padStart(2,'0')}.${String(n%1000).padStart(3,'0')}`:'—'}function table(headers,rows){const outer=node('div','table-wrap'),t=node('table'),thead=node('thead'),tr=node('tr');headers.forEach(x=>tr.append(node('th','',x)));thead.append(tr);t.append(thead);const body=node('tbody');rows.forEach(row=>{const tr=node('tr');row.forEach(v=>{const cell=node('td');if(v instanceof Node)cell.append(v);else cell.textContent=String(v??'—');tr.append(cell)});body.append(tr)});t.append(body);outer.append(t);return outer}function status(text){const root=$('#results');root.replaceChildren(node('p','empty',text))}async function get(path){const r=await fetch(api+path,{signal:AbortSignal.timeout(10000)});if(!r.ok)throw Error(r.status);return r.json()}function profileLink(d){return d.profile_id?link(d.display_name||'—',base+'profile.html?driver='+encodeURIComponent(d.profile_id)):node('span','',d.display_name||'—')}async function events(){const root=$('#results');if(game==='ace'){status(labels.none);return}try{const d=await get('/public-event');const items=d.events||[];if(!items.length)return status(labels.none);root.replaceChildren();const grid=node('div','grid');items.forEach(e=>{const card=node('article','panel');card.append(node('span','meta',e.event_type||'ACC'),node('h3','',e['title_'+lang]||e.title_en||e.title_fr||e.circuit_name),node('p','',e.circuit_name+' · '+date(e.starts_at)));const u=safeExternal(e.simgrid_url);if(u){const a=link(labels.register,u);a.target='_blank';a.rel='noopener noreferrer';card.append(a)}grid.append(card)});root.append(grid)}catch{status(labels.offline);historical(root)}}function historical(root){const note=node('div','panel');note.append(node('span','meta',labels.archive),node('h3','','Monza · 1 septembre 2026'));const a=link(labels.legacy,'https://athoxmotorsport-lab.github.io/atx-racing/archives.html');note.append(a);root.append(note)}async function rankings(){if(game==='ace')return status(labels.none);const type=$('#category')?.value||'DR';const root=$('#results');root.replaceChildren(node('p','loading',labels.loading));try{const d=await get('/public-leaderboard?category='+encodeURIComponent(type));const drivers=(d.drivers||[]).map(x=>[x.rank,profileLink(x),x.team_name||'—',x.primary_car||'—',x.races,x.wins,x.podiums,x.points]);root.replaceChildren(drivers.length?table(['#',labels.driver,labels.team,labels.car,labels.races,labels.wins,labels.podiums,labels.points],drivers):node('p','empty',labels.none))}catch{status(labels.offline)}}async function records(){if(game==='ace')return status(labels.none);const root=$('#results');root.replaceChildren(node('p','loading',labels.loading));try{const d=await get('/public-leaderboard?category=ALL');const circuits=d.circuits||[];const select=$('#circuit');select.replaceChildren();circuits.forEach((c,i)=>{const o=node('option','',c.circuit_name);o.value=i;select.append(o)});function render(){const c=circuits[Number(select.value)];root.replaceChildren(c?table(['#',labels.driver,labels.car,labels.lap,labels.date],c.drivers.map((d,i)=>[i+1,profileLink(d),d.car_model_name||'—',lap(d.best_lap_ms),date(d.achieved_at)])):node('p','empty',labels.none))}select.onchange=render;render()}catch{status(labels.offline)}}async function profile(){if(game==='ace')return status(labels.none);const id=new URLSearchParams(location.search).get('driver');if(!id)return status(labels.none);try{const d=(await get('/public-driver?driver='+encodeURIComponent(id))).driver;const root=$('#results');root.replaceChildren();const card=node('section','panel');const top=node('div','profile-top');if(d.avatar_url){const pic=node('img','avatar');pic.src=d.avatar_url;pic.alt='';top.append(pic)}const info=node('div');info.append(node('span','meta',d.team_name||'ATXRACING'),node('h2','',d.display_name));top.append(info);card.append(top);const bio=d['bio_'+lang]||d.bio_en||d.bio_fr;if(bio)card.append(node('p','',bio));const stats=node('div','stats');[[labels.races,d.stats?.races],[labels.wins,d.stats?.wins],[labels.podiums,d.stats?.podiums],[labels.points,d.stats?.points]].forEach(([k,v])=>{const b=node('div','stat');b.append(node('b','',v??0),node('small','',k));stats.append(b)});card.append(stats);root.append(card);if(d.results?.length){root.append(node('h2','',labels.races),table([labels.date,labels.circuit,labels.car,labels.points,labels.lap],d.results.map(r=>[date(r.event?.starts_at),r.event?.circuit_name,r.car_model_name,r.points,lap(r.best_lap_ms)])))}root.append(link(labels.legacy,'https://athoxmotorsport-lab.github.io/atx-racing/profil-pilote.html?driver='+encodeURIComponent(id)))}catch{status(labels.offline)}}if(page==='courses')events();if(page==='rankings'){rankings();$('#category').onchange=rankings}if(page==='records')records();if(page==='profile')profile();
